using UnityEngine;
using System.Collections.Generic;

public static class MarchingCubes
{
    public static Mesh GenerateMesh(float[,,] grid, float isoLevel)
    {
        Mesh mesh = new Mesh();
        List<Vector3> vertices = new List<Vector3>();
        List<int> triangles = new List<int>();
        int width = grid.GetLength(0);
        int height = grid.GetLength(1);
        int depth = grid.GetLength(2);

        for (int x = 0; x < width - 1; x++)
        for (int y = 0; y < height - 1; y++)
        for (int z = 0; z < depth - 1; z++)
        {
            Vector3[] cornerPositions = new Vector3[8];
            float[] cornerValues = new float[8];
            for (int i = 0; i < 8; i++)
            {
                cornerPositions[i] = new Vector3(x + vertexOffset[i, 0], y + vertexOffset[i, 1], z + vertexOffset[i, 2]);
                cornerValues[i] = grid[x + vertexOffset[i, 0], y + vertexOffset[i, 1], z + vertexOffset[i, 2]];
            }

            int cubeIndex = 0;
            if (cornerValues[0] < isoLevel) cubeIndex |= 1;
            if (cornerValues[1] < isoLevel) cubeIndex |= 2;
            if (cornerValues[2] < isoLevel) cubeIndex |= 4;
            if (cornerValues[3] < isoLevel) cubeIndex |= 8;
            if (cornerValues[4] < isoLevel) cubeIndex |= 16;
            if (cornerValues[5] < isoLevel) cubeIndex |= 32;
            if (cornerValues[6] < isoLevel) cubeIndex |= 64;
            if (cornerValues[7] < isoLevel) cubeIndex |= 128;

            if (edgeTable[cubeIndex] == 0) continue;

            Vector3[] vertList = new Vector3[12];
            if ((edgeTable[cubeIndex] & 1) != 0) vertList[0] = InterpolateVertex(isoLevel, cornerPositions[0], cornerPositions[1], cornerValues[0], cornerValues[1]);
            if ((edgeTable[cubeIndex] & 2) != 0) vertList[1] = InterpolateVertex(isoLevel, cornerPositions[1], cornerPositions[2], cornerValues[1], cornerValues[2]);
            if ((edgeTable[cubeIndex] & 4) != 0) vertList[2] = InterpolateVertex(isoLevel, cornerPositions[2], cornerPositions[3], cornerValues[2], cornerValues[3]);
            if ((edgeTable[cubeIndex] & 8) != 0) vertList[3] = InterpolateVertex(isoLevel, cornerPositions[3], cornerPositions[0], cornerValues[3], cornerValues[0]);
            if ((edgeTable[cubeIndex] & 16) != 0) vertList[4] = InterpolateVertex(isoLevel, cornerPositions[4], cornerPositions[5], cornerValues[4], cornerValues[5]);
            if ((edgeTable[cubeIndex] & 32) != 0) vertList[5] = InterpolateVertex(isoLevel, cornerPositions[5], cornerPositions[6], cornerValues[5], cornerValues[6]);
            if ((edgeTable[cubeIndex] & 64) != 0) vertList[6] = InterpolateVertex(isoLevel, cornerPositions[6], cornerPositions[7], cornerValues[6], cornerValues[7]);
            if ((edgeTable[cubeIndex] & 128) != 0) vertList[7] = InterpolateVertex(isoLevel, cornerPositions[7], cornerPositions[4], cornerValues[7], cornerValues[4]);
            if ((edgeTable[cubeIndex] & 256) != 0) vertList[8] = InterpolateVertex(isoLevel, cornerPositions[0], cornerPositions[4], cornerValues[0], cornerValues[4]);
            if ((edgeTable[cubeIndex] & 512) != 0) vertList[9] = InterpolateVertex(isoLevel, cornerPositions[1], cornerPositions[5], cornerValues[1], cornerValues[5]);
            if ((edgeTable[cubeIndex] & 1024) != 0) vertList[10] = InterpolateVertex(isoLevel, cornerPositions[2], cornerPositions[6], cornerValues[2], cornerValues[6]);
            if ((edgeTable[cubeIndex] & 2048) != 0) vertList[11] = InterpolateVertex(isoLevel, cornerPositions[3], cornerPositions[7], cornerValues[3], cornerValues[7]);

            for (int i = 0; triTable[cubeIndex, i] != -1; i += 3)
            {
                vertices.Add(vertList[triTable[cubeIndex, i]]);
                vertices.Add(vertList[triTable[cubeIndex, i + 1]]);
                vertices.Add(vertList[triTable[cubeIndex, i + 2]]);
                triangles.Add(vertices.Count - 3);
                triangles.Add(vertices.Count - 2);
                triangles.Add(vertices.Count - 1);
            }
        }

        mesh.vertices = vertices.ToArray();
        mesh.triangles = triangles.ToArray();
        mesh.RecalculateNormals();
        return mesh;
    }

    private static Vector3 InterpolateVertex(float iso, Vector3 p1, Vector3 p2, float v1, float v2)
    {
        if (Mathf.Abs(iso - v1) < 0.00001f) return p1;
        if (Mathf.Abs(iso - v2) < 0.00001f) return p2;
        if (Mathf.Abs(v1 - v2) < 0.00001f) return p1;
        return p1 + (iso - v1) / (v2 - v1) * (p2 - p1);
    }

